python3 << 'EOF'
import pandas as pd, io, json
import numpy as np

def load_raw_text(fn):
    with open(fn,'rb') as f:
        raw = f.read()
    if raw[:2] == b'\xff\xfe':
        return raw.decode('utf-16')
    return raw.decode('utf-8')

def load_df_raw(c):
    fn = f'production_FARM_{c}.csv'
    text = load_raw_text(fn)
    lines = text.split('\n')
    header = lines[3]
    delim = ';' if ';' in header else ','
    data_text = '\n'.join(lines[3:])
    df = pd.read_csv(io.StringIO(data_text), delimiter=delim, dtype=str)
    df.columns = [col.replace('\t','') for col in df.columns]
    return df, delim

def parse_ts(s):
    if pd.isna(s): return pd.NaT
    s = s.strip()
    for fmt in ('%Y-%m-%d %H:%M:%S','%d.%m.%Y %H:%M:%S'):
        try:
            return pd.to_datetime(s, format=fmt)
        except Exception:
            continue
    return pd.NaT

def parse_num(s, delim):
    if pd.isna(s): return np.nan
    s = s.strip()
    if s.lower() in ('timeout','offline','err','error','') : return np.nan
    if s in ('-999.0','888888.8'): return np.nan
    try:
        if delim==';':
            return float(s.replace('.','').replace(',','.'))
        return float(s)
    except:
        return np.nan

for c in 'ABCDEFGHIJKLMNOPQRSTUVWX':
    df, delim = load_df_raw(c)
    ts = df['timestamp'].apply(parse_ts)
    temp = df['inverter_temperature_C'].apply(lambda s: parse_num(s, delim))
    valid = ts.notna()
    ts_valid = ts[valid].sort_values()
    diffs = ts_valid.diff().dropna()
    mode_interval = diffs.mode()[0] if len(diffs)>0 else None
    max_temp = temp.max()
    n_spike = (temp>85.0).sum()
    print(f'FARM_{c}: interval={mode_interval} max_temp={max_temp:.2f} n_spike(>85)={n_spike} span=({ts_valid.min()} to {ts_valid.max()})')
EOF

