import io
import json
from zoneinfo import ZoneInfo

import numpy as np
import pandas as pd

DATASET = "/app/dataset"

WINDOW_START_UTC = pd.Timestamp("2024-03-15 00:00:00", tz="UTC")
WINDOW_END_UTC = pd.Timestamp("2024-03-16 00:00:00", tz="UTC")

SENTINEL_STRINGS = {"timeout", "offline", "err", "error"}
SENTINEL_EXACT = {"-999.0", "888888.8"}

UNIT_TO_KWH_FACTOR = {
    "kwh": 1.0,
    "mwh": 1000.0,
    "wh": 0.001,
    "btu": 0.00029307107,
}

# (farm_id, tz_name, local_start, local_end, completed)
MAINTENANCE_WINDOWS = [
    ("FARM_C", "Asia/Tokyo", "2024-03-16 08:00:00", "2024-03-16 12:00:00", True),
    ("FARM_C", "Asia/Tokyo", "2024-03-15 09:00:00", "2024-03-15 11:00:00", False),
    ("FARM_F", "Europe/Warsaw", "2024-03-15 12:00:00", "2024-03-15 14:00:00", True),
]

TEMP_SPIKE_THRESHOLD_C = 85.0
TEMP_SPIKE_INVALIDATION_MINUTES = 45


def load_farm_metadata():
    farms = pd.read_csv(f"{DATASET}/farms.csv")
    registry = pd.read_csv(f"{DATASET}/farm_registry.csv")
    farms["farm_name_clean"] = farms["farm_name"].str.strip().str.lower()
    registry["farm_name_clean"] = registry["farm_name"].str.strip().str.lower()
    merged = registry.merge(farms, on="farm_name_clean", how="left")
    return merged.set_index("farm_id")[["timezone", "installed_capacity_kw"]].to_dict("index")


def load_calibration():
    with open(f"{DATASET}/sensors_calibration.json") as f:
        data = json.load(f)
    return data["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]


def read_production_text(farm_letter):
    fn = f"{DATASET}/production_FARM_{farm_letter}.csv"
    with open(fn, "rb") as f:
        raw = f.read()
    if raw[:2] == b"\xff\xfe":
        return raw.decode("utf-16")
    return raw.decode("utf-8")


def load_production_df(farm_letter):
    text = read_production_text(farm_letter)
    lines = text.split("\n")
    header = lines[3]
    delim = ";" if ";" in header else ","
    data_text = "\n".join(lines[3:])
    df = pd.read_csv(io.StringIO(data_text), delimiter=delim, dtype=str)
    df.columns = [col.replace("\t", "") for col in df.columns]
    df = df.drop_duplicates()
    return df, delim


def parse_timestamp(s):
    if pd.isna(s):
        return pd.NaT
    s = s.strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S"):
        try:
            return pd.to_datetime(s, format=fmt)
        except (ValueError, TypeError):
            continue
    return pd.NaT


def parse_numeric(s, delim):
    if pd.isna(s):
        return np.nan
    s = s.strip()
    if s == "" or s.lower() in SENTINEL_STRINGS or s in SENTINEL_EXACT:
        return np.nan
    try:
        if delim == ";":
            return float(s.replace(".", "").replace(",", "."))
