    farms = pd.read_csv(f"{DATASET}/farms.csv")
    registry = pd.read_csv(f"{DATASET}/farm_registry.csv")
    farms["farm_name_clean"] = farms["farm_name"].str.strip().str.lower()
    registry["farm_name_clean"] = registry["farm_name"].str.strip().str.lower()
    merged = registry.merge(farms, on="farm_name_clean", how="left")
    return merged.set_index("farm_id")[["timezone", "installed_capacity_kw"]].to_dict("index")


def load_calibration():
    with open(f"{DATASET}/sensors_calibration.json") as f:
        data = json.load(f)
    return data["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]


def read_production_text(farm_letter):
    fn = f"{DATASET}/production_FARM_{farm_letter}.csv"
    with open(fn, "rb") as f:
        raw = f.read()
    if raw[:2] == b"\xff\xfe":
        return raw.decode("utf-16")
    return raw.decode("utf-8")


def load_production_df(farm_letter):
    text = read_production_text(farm_letter)
    lines = text.split("\n")
    header = lines[3]
    delim = ";" if ";" in header else ","
    data_text = "\n".join(lines[3:])
    df = pd.read_csv(io.StringIO(data_text), delimiter=delim, dtype=str)
    df.columns = [col.replace("\t", "") for col in df.columns]
    df = df.drop_duplicates()
    return df, delim


def parse_timestamp(s):
    if pd.isna(s):
        return pd.NaT
    s = s.strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%d.%m.%Y %H:%M:%S"):
        try:
            return pd.to_datetime(s, format=fmt)
        except (ValueError, TypeError):
            continue
    return pd.NaT


def parse_numeric(s, delim):
    if pd.isna(s):
        return np.nan
    s = s.strip()
    if s == "" or s.lower() in SENTINEL_STRINGS or s in SENTINEL_EXACT:
        return np.nan
    try:
        if delim == ";":
            return float(s.replace(".", "").replace(",", "."))
        return float(s)
    except ValueError:
        return np.nan


def sampling_interval_hours(timestamps):
    valid = timestamps.dropna().sort_values().unique()
    diffs = pd.Series(valid).diff().dropna()
    if diffs.empty:
        return 0.0
    mode_diff = diffs.mode().iloc[0]
    return mode_diff / pd.Timedelta(hours=1)


def apply_temperature_safety_rule(df):
    spike_times = df.loc[df["inverter_temperature_C"] > TEMP_SPIKE_THRESHOLD_C, "timestamp"]
    if spike_times.empty:
        return df
    invalid_mask = pd.Series(False, index=df.index)
    window = pd.Timedelta(minutes=TEMP_SPIKE_INVALIDATION_MINUTES)
    for spike_time in spike_times:
        invalid_mask |= (df["timestamp"] > spike_time) & (df["timestamp"] <= spike_time + window)
    return df[~invalid_mask]


def maintenance_exclusion_mask(farm_id, timestamps_utc):
    mask = pd.Series(False, index=timestamps_utc.index)
    for wfarm, tz_name, local_start, local_end, completed in MAINTENANCE_WINDOWS:
        if wfarm != farm_id or not completed:
            continue
        tz = ZoneInfo(tz_name)
        start_utc = pd.Timestamp(local_start, tz=tz).astimezone(ZoneInfo("UTC"))
        end_utc = pd.Timestamp(local_end, tz=tz).astimezone(ZoneInfo("UTC"))
        mask |= (timestamps_utc >= start_utc) & (timestamps_utc < end_utc)
    return mask


def compute_farm_kwh(farm_letter, calibration):
    farm_id = f"FARM_{farm_letter}"
    cal = calibration[farm_id]["calibration_data"]
    sensor = calibration[farm_id]["sensor_info"]
    value_col = cal["value_column_name"]
    offset = cal["calibration_offset"]
    reading_type = sensor["reading_type"]
    unit = sensor["unit"].lower()

    df, delim = load_production_df(farm_letter)

    df["timestamp"] = df["timestamp"].apply(parse_timestamp)
    df["inverter_temperature_C"] = df["inverter_temperature_C"].apply(lambda s: parse_numeric(s, delim))
    df["value_parsed"] = df[value_col].apply(lambda s: parse_numeric(s, delim))

    df = df.dropna(subset=["timestamp", "value_parsed"])
    df = df.drop_duplicates(subset=["timestamp", "value_parsed"])

    interval_hours = sampling_interval_hours(df["timestamp"])

    df["true_value"] = df["value_parsed"] - offset
    df = df[df["true_value"] >= 0]

    df = apply_temperature_safety_rule(df)

    df = df.assign(timestamp_utc=df["timestamp"].dt.tz_localize("UTC"))
    excluded = maintenance_exclusion_mask(farm_id, df["timestamp_utc"])
    df = df[~excluded]

    in_window = (df["timestamp_utc"] >= WINDOW_START_UTC) & (df["timestamp_utc"] < WINDOW_END_UTC)
    df = df[in_window]

    if df.empty:
        return 0

    if reading_type == "energy":
        factor = UNIT_TO_KWH_FACTOR[unit]
        kwh_series = df["true_value"] * factor
    else:
        kwh_series = df["true_value"] * interval_hours

    total_kwh = kwh_series.sum()
    return round(total_kwh)


def answer() -> dict:
    calibration = load_calibration()
    result = {}
    for letter in calibration.keys():
        farm_letter = letter.replace("FARM_", "")
        result[letter] = compute_farm_kwh(farm_letter, calibration)
    return result


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

